mission.script:
if alive_count("player") == 1 && flag("warned") == 0 {
  set_flag("warned", 1);
  message("Last soldier standing - get to the objective!");
}

fn evac(inside, squad, done) {
  if squad > 0 && inside >= squad { message(done); win(); }
  else { message(inside + " of " + squad + " soldiers at the evac point - everyone still alive has to make it."); }
}
